/*
 * A257903  Sequence (a(n)) generated by Algorithm (in Comments) with a(1) = 0
 *          and d(1) = 3.
 * https://oeis.org/A257903
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 177, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Algorithm: generates sequence A257903 (a(1)=0, d(1)=3) as
 * described in the OEIS comments.  The function memoises already
 * built terms so calls may arrive in any order.  It assumes the
 * difference values fit in a signed 64‑bit integer.  For first
 * 10 000 terms this is sufficient and stays well under the time
 * limit. */
#include <stdlib.h>
#include <stdint.h>

static void ensure_capacity(size_t *len, size_t *cap, void **arr, size_t elem_size)
{
    if (*len >= *cap) {
        size_t newcap = (*cap == 0) ? 8 : (*cap << 1);
        void *tmp = realloc(*arr, newcap * elem_size);
        if (!tmp) exit(EXIT_FAILURE);
        *arr = tmp;
        *cap = newcap;
    }
}

seq_t a(idx_t n)
{
    /* static state preserved between calls */
    static seq_t *A   = NULL;   /* array of a(k) */
    static size_t A_len = 0, A_cap = 0;

    static long long *D   = NULL;   /* array of differences d(k) */
    static size_t D_len = 0, D_cap = 0;

    static seq_t last_a = 0;   /* a(k) of the current last term */

    /* initialise on the first call */
    if (A == NULL) {
        A_cap = 8;
        A = (seq_t*)calloc(A_cap, sizeof(seq_t));
        D_cap = 8;
        D = (long long*)calloc(D_cap, sizeof(long long));

        /* a(1) = 0, d(1) = 3 */
        A[0] = (seq_t)0;
        D[0] = 3;
        A_len = 1;
        D_len = 1;
        last_a = (seq_t)0;
    }

    /* generate terms until we reach index n (1‑based) */
    while (A_len < (size_t)n) {
        /* h must be the least integer > -last_a */
        long long h_start = -(long long)last_a + 1;
        long long h;

        for (h = h_start; ; ++h) {
            /* check if h is already used in D */
            int h_used = 0;
            for (size_t i = 0; i < D_len; ++i) {
                if (D[i] == h) { h_used = 1; break; }
            }
            if (h_used) continue;

            /* candidate a(k)+h (ensure non‑negative) */
            seq_t cand;
            if (h >= 0)
                cand = last_a + (seq_t)h;
            else
                cand = last_a - (seq_t)(-h);

            if (cand < (seq_t)0) continue;          /* would be negative */

            /* check if cand already occurs in A */
            int cand_used = 0;
            for (size_t i = 0; i < A_len; ++i) {
                if (A[i] == cand) { cand_used = 1; break; }
            }
            if (cand_used) continue;

            /* valid h found */
            break;
        }

        /* store new term and difference */
        ensure_capacity(&A_len, &A_cap, (void **)&A, sizeof(seq_t));
        ensure_capacity(&D_len, &D_cap, (void **)&D, sizeof(long long));

        seq_t a_next = (h >= 0) ? last_a + (seq_t)h : last_a - (seq_t)(-h);
        A[A_len] = a_next;
        D[D_len] = h;

        last_a = a_next;
        ++A_len;
        ++D_len;
    }

    return A[(size_t)n - 1];
}
